// Get canvas and context
const canvas = document.querySelector("canvas");
const ctx = canvas.getContext("2d");

// Set fixed canvas size
canvas.width = 400;
canvas.height = 400;

// Main animation function
function animateShape() {
  const currentTime = new Date().getTime() / 10; // Time for animation in milliseconds
  const heightScale = 0.9 + Math.sin(currentTime / 100) * 0.3; // Pulsing height factor

  // Clear canvas with solid black
  ctx.globalCompositeOperation = "source-over";
  ctx.fillStyle = "rgb(0, 0, 0)";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Set glowing style for shape
  ctx.globalCompositeOperation = "lighter"; // Blend mode for glow effect
  ctx.strokeStyle = "hsla(244, 60%, 60%, 0.3)"; // Semi-transparent purple
  ctx.fillStyle = "hsla(244, 60%, 60%, 0.3)";

  // Generate and render the shape
  const shapePoints = generatePoints(currentTime, heightScale);
  renderShape(shapePoints, heightScale);

  // Continue animation
  requestAnimationFrame(animateShape);
}

// Generate points for the shape
function generatePoints(currentTime, heightScale) {
  const pointsArray = [];

  // Top semi-circle of the shape
  for (let i = 0; i < 180; i++) {
    const ratio = (i + 1) / 180; // Progress from 0 to 1
    const horizontalScale = Math.cos((ratio * Math.PI) / 2); // X scaling
    const verticalScale = Math.sin((ratio * Math.PI) / 2); // Y scaling
    const inverseRatio = 1 - ratio;

    const segmentPoints = calculatePoints(
      100 * horizontalScale,
      inverseRatio,
      horizontalScale,
      verticalScale,
      heightScale,
      currentTime
    );
    pointsArray.push(segmentPoints);
  }

  // Bottom arc of the shape
  for (let i = 0; i < 100; i++) {
    const ratio = (i + 1) / 100; // Progress from 0 to 1
    const segmentPoints = calculatePoints(
      100 * ratio,
      ratio,
      ratio,
      0,
      heightScale,
      currentTime
    );
    pointsArray.push(segmentPoints);
  }

  return pointsArray;
}

// Calculate points for a segment of the shape
function calculatePoints(pointCount, ratio, horizontalScale, verticalScale, heightScale, currentTime) {
  const points = [];
  const angleStep = (Math.PI * 2) / pointCount; // Angle increment per point

  for (let i = 0; i < pointCount; i++) {
    const angle = i * angleStep;
    let x = Math.cos(angle) * horizontalScale; // Base X position
    let y = Math.sin(angle) * horizontalScale; // Base Y position
    const zOffset = calculateZOffset(angle, ratio, currentTime); // Depth offset
    x -= zOffset * ratio; // Adjust X with depth

    // Store transformed point [x, y, z]
    points.push([x, y, heightScale + zOffset * ratio + verticalScale]);
  }
  return points;
}

// Calculate Z offset for wave-like motion
function calculateZOffset(angle, ratio, currentTime) {
  return (
    Math.sin(angle * 2 - currentTime / 13 + ratio * 13) / 20 + // First wave
    Math.sin(angle * 5 - currentTime / 17 + ratio * 13) / 20 + // Second wave
    Math.sin(angle * 7 - currentTime / 19 + ratio * 13) / 40   // Third wave
  );
}

// Render the shape by drawing lines between points
function renderShape(pointsArray, heightScale) {
  pointsArray.forEach((points) => {
    const transformedPoints = points.map(([x, y, z]) => {
      const scaleFactor = Math.pow(1.5, y / 2); // Perspective scaling

      return [
        x * scaleFactor * 150 + 200, // X position centered on canvas
        z * scaleFactor * 200 - heightScale * 200 + 150, // Y position with height adjustment
      ];
    });

    // Draw the shape outline
    ctx.beginPath();
    transformedPoints.forEach(([x, y]) => {
      ctx.lineTo(x, y);
    });
    ctx.closePath();
    ctx.stroke();
  });
}

// Start the animation
animateShape();
